  '[["Recurring giving allowed\\n' => 'العطاء المتكرر مسموح به',
  '\\nLinked forms\\n' => 'النماذج المرتبطة',
  '\\nGifts through these Flux Forms forms count for this type. Map each priced choice of the form to an option: the form then charges the price set here.\\n' => 'يتم احتساب الهدايا من خلال نماذج Flux Forms لهذا النوع. قم بتعيين كل اختيار مسعر للنموذج إلى خيار: يقوم النموذج بعد ذلك بتحصيل السعر المحدد هنا.',
  '\\nNo payment form found in Flux Forms yet.\\n' => 'لم يتم العثور على نموذج دفع في Flux Forms حتى الآن.',
  '\\nalso linked to:%s\\n' => 'مرتبط أيضًا بـ: %s',
  '\\nSave after choosing a form to map its choices.\\n' => 'احفظ بعد اختيار نموذج لتعيين اختياراته.',
  '\\nHide the choice in the form when it was preselected\\n' => 'إخفاء الاختيار في النموذج عندما تم تحديده مسبقاً',
  '\\nWhen the page passes a choice (flxb_opt in the address or FLXB.preselect()), the form shows a short summary with a "Change" link instead of the choice list.\\n' => 'عندما تمرر الصفحة اختيارًا (flxb_opt في العنوان أو FLXB.preselect())، يعرض النموذج ملخصًا قصيرًا مع ارتباط "تغيير" بدلاً من قائمة الاختيار.',
  'Publishing' => 'النشر',
  '\\nA closed type keeps its history but its forms no longer take payments.\\n' => 'يحتفظ النوع المغلق بمحفوظاته ولكن نماذجه لم تعد تقبل الدفعات.',
