  '\\nProxy (vekâlet) required\\n' => 'الوكيل (vekâlet) مطلوب',
  '\\nAnimal\\n' => 'الحيوان',
  '\\nCattle (7 shares)\\n' => 'الماشية (7 أسهم)',
