  '[[\'%srecurring donation\', \'en\']]' . chr(0) . '[[\'%srecurring donations\', \'en\']]' => 'تبرعات %sالمتكررة' . chr(0) . 'تبرع متكرر بـ%s' . chr(0) . 'تبرعات %sالمتكررة' . chr(0) . 'تبرعات %sالمتكررة' . chr(0) . 'تبرعات %sالمتكررة' . chr(0) . 'تبرعات %sالمتكررة',
