  '\\nEsnekPOS payment received: reference%1$s,%2$sinstallment(s),%3$scharged.\\n' => 'تم استلام دفعة EsnekPOS: المرجع%1$s، قسط (دفعات)%2$s، مشحونة %3$s.',
