  '\\nName, full address, district / city, phone\', \'en\']]' => 'الاسم، العنوان الكامل، المنطقة / المدينة، رقم الهاتف\'، \'en\']]',
  '\\nBy card, stop any time.\\n' => 'بالبطاقة، توقف في أي وقت.',
