  'Continue' => 'متابعة',
  'Add to cart' => 'أضف إلى السلة',
  '\\nfrom%s\\n' => 'من%s',
  '\\nPayments are taken securely by iyzico.\\n' => 'يتم تحصيل الدفعات بشكل آمن بواسطة iyzico.',
  '\\nPay safely by card or bank transfer.\\n' => 'ادفع بأمان عن طريق البطاقة أو التحويل المصرفي.',
  '\\nYour card details are never stored on our site.\\n' => 'لا يتم تخزين تفاصيل بطاقتك على موقعنا أبدًا.',
  '\\nHow many saplings would you like to donate?\\n' => 'كم عدد الشجيرات التي ترغب في التبرع بها؟',
  '\\nAnother amount\\n' => 'مبلغ آخر',
  'Fewer' => 'أقل',
  'Number of saplings' => 'عدد الشتلات',
  'More' => 'المزيد',
  'Donation amount' => 'مبلغ التبرع',
