  '\\niyzico keys\\n' => 'iyzico مفاتيح',
  'Test connection' => 'اتصال الاختبار',
  '\\nPaste into iyzico panel › Merchant notifications URL (İşyeri Bildirimleri Url):%s. Subscription notification URLs are not needed.\\n' => 'الصق في لوحة iyzico › عنوان URL لإشعارات التاجر (عنوان Url لـ Bildirimleri): %s. ليست هناك حاجة إلى عناوين URL لإشعارات الاشتراك.',
  '\\nLast notification received:%s.\\n' => 'آخر إشعار تم تلقيه: %s.',
  '\\nNo notification received in the last 30 days (normal until the address is saved in the iyzico panel and a payment is made).\\n' => 'لم يتم تلقي أي إشعار خلال آخر 30 يومًا (الأمر الطبيعي حتى يتم حفظ العنوان في لوحة iyzico ويتم إجراء الدفع).',
  '\\nNotifications for WooCommerce orders are forwarded to the iyzico WooCommerce plugin.\\n' => 'تتم إعادة توجيه إعلامات طلبات WooCommerce إلى البرنامج الإضافي iyzico WooCommerce.',
  '\\niyzico notification URL\\n' => 'iyzico عنوان URL للإشعار',
  '\\nShow addresses\\n' => 'إظهار العناوين',
  '\\nFailed recurring charges\\n' => 'فشل في تحصيل الرسوم المتكررة',
  '[[\'%drecurring donation stopped after its card was declined 3 times.\', \'en\']]' . chr(0) . '[[\'%drecurring donations stopped after their cards were declined 3 times.\', \'en\']]' => 'توقفت التبرعات المتكررة لـ%dبعد أن تم رفض بطاقاتهم 3 مرات.' . chr(0) . 'توقف التبرع المتكرر لـ%dبعد رفض بطاقته 3 مرات.' . chr(0) . 'توقفت التبرعات المتكررة لـ%dبعد أن تم رفض بطاقاتهم 3 مرات.' . chr(0) . 'توقفت التبرعات المتكررة لـ%dبعد أن تم رفض بطاقاتهم 3 مرات.' . chr(0) . 'توقفت التبرعات المتكررة لـ%dبعد أن تم رفض بطاقاتهم 3 مرات.' . chr(0) . 'توقفت التبرعات المتكررة لـ%dبعد أن تم رفض بطاقاتهم 3 مرات.',
  '\\nStripe keys\\n' => 'مفاتيح شريطية',
  '\\nThe Stripe publishable key and secret key are missing.\\n' => 'مفتاح Stripe القابل للنشر والمفتاح السري مفقودان.',
  '\\nMode: live.\\n' => 'الوضع: مباشر.',
  '\\nMode: test (pk_test_). No real money is collected.\\n' => 'الوضع: اختبار (pk_test_). لم يتم جمع أي أموال حقيقية.',
  '\\nWebhook signing secret is set.\\n' => 'تم تعيين سر توقيع Webhook.',
  '\\nWebhook signing secret is missing: refunds and renewals made in Stripe will not show up in Flux Donate.\\n' => 'سر توقيع Webhook مفقود: لن تظهر المبالغ المستردة والتجديدات التي تم إجراؤها في Stripe في Flux Donate.',
  '\\nFlux Forms is not active. Donation forms and card payments need it.\\n' => 'نماذج التمويه غير نشطة. تحتاج نماذج التبرعات ومدفوعات البطاقات إلى ذلك.',
  '\\nActive, version%s.\\n' => 'نشط، الإصدار%s.',
  '\\nVersion%1$sis active; Flux Donate needs%2$sor later for payments and prices to work together.\\n' => 'الإصدار%1$sنشط؛ يحتاج Flux Donate إلى%2$sأو إصدار أحدث حتى تعمل الدفعات والأسعار معًا.',
  '\\nActive, version%s. Certificates can be sent after donations.\\n' => 'نسخة نشطة%s. يمكن إرسال الشهادات بعد التبرعات.',
  '\\nVersion%1$sis active;%2$sor later is recommended.\\n' => 'الإصدار%1$sنشط؛ يوصى باستخدام %2$sأو الإصدارات الأحدث.',
  '\\nNot active. Donations are recorded, but no certificate is created or sent.\\n' => 'غير نشط. يتم تسجيل التبرعات، لكن لا يتم إنشاء أو إرسال أي شهادة.',
  '\\nWooCommerce is older than%s. Flux Donate 2.0 takes donations through WooCommerce; update it.\\n' => 'WooCommerce أقدم من%s. يأخذ Flux Donate 2.0 التبرعات من خلال WooCommerce؛ قم بتحديثه.',
  '\\nWooCommerce is not active. Flux Donate 2.0 takes donations through the WooCommerce cart and checkout; until it is active, only the older Flux Forms payment layer works.\\n' => 'WooCommerce غير نشط. يتلقى Flux Donate 2.0 التبرعات من خلال عربة التسوق WooCommerce والخروج؛ حتى تصبح نشطة، تعمل طبقة الدفع القديمة فقط في Flux Forms.',
  '[[\'The old Flux WooCommerce Bağış plugin is still active. Flux Donate 2.0 replaces it: deactivate and delete it, otherwise orders get two certificates and two messages.\\n' => 'لا يزال البرنامج الإضافي Flux WooCommerce Bağış القديم نشطًا. يستبدله Flux Donate 2.0: قم بإلغاء تنشيطه وحذفه، وإلا ستحصل الطلبات على شهادتين ورسالتين.',
  '\\nWooCommerce is active.\\n' => 'WooCommerce نشط.',
  '\\nThe iyzico WooCommerce plugin is active: it takes one-time card payments, and Flux Donate reads its iyzico keys for monthly donations.\\n' => 'المكون الإضافي iyzico WooCommerce نشط: فهو يقبل دفعات البطاقة لمرة واحدة، ويقرأ Flux Donate مفاتيح iyzico الخاصة به للحصول على تبرعات شهرية.',
  '\\nThe iyzico WooCommerce plugin is not active, but its saved keys are still used.\\n' => 'الملحق iyzico WooCommerce غير نشط، لكن مفاتيحه المحفوظة لا تزال قيد الاستخدام.',
  '\\nThe iyzico WooCommerce plugin is not active; Flux Donate uses its own iyzico keys.\\n' => 'الملحق iyzico WooCommerce غير نشط؛ يستخدم Flux Donate مفاتيح iyzico الخاصة به.',
  '\\nThe iyzico Subscription plugin is active; it renews WooCommerce subscriptions only. Flux Donate recurring donations use their own hourly task.\', \'en\']]' => 'المكون الإضافي للاشتراك iyzico نشط؛ يقوم بتجديد اشتراكات WooCommerce فقط. Flux Donate تستخدم التبرعات المتكررة مهمتها الخاصة بالساعة.',
  '\\nWooCommerce and iyzico plugins\\n' => 'مكونات WooCommerce وiyzico الإضافية',
  '[[\'Open donation types\\n' => 'أنواع التبرع المفتوحة',
  '[[\'%ddonation type is open and priced.\', \'en\']]' . chr(0) . '[[\'%ddonation types are open and priced.\', \'en\']]' => 'أنواع التبرعات لـ%dمفتوحة ومسعرة.' . chr(0) . 'نوع التبرع %dمفتوح وسعره.' . chr(0) . 'أنواع التبرعات لـ%dمفتوحة ومسعرة.' . chr(0) . 'أنواع التبرعات لـ%dمفتوحة ومسعرة.' . chr(0) . 'أنواع التبرعات لـ%dمفتوحة ومسعرة.' . chr(0) . 'أنواع التبرعات لـ%dمفتوحة ومسعرة.',
  '\\nNo donation type is open with a price (or free amount), so forms cannot take donations.\\n' => 'لا يوجد نوع تبرع مفتوح بسعر (أو مبلغ مجاني)، لذلك لا يمكن للنماذج قبول التبرعات.',
  '\\nForms of open donation types\\n' => 'نماذج أنواع التبرعات المفتوحة',
  '\\nNo (existing) form is linked to:%s. Visitors cannot give to these types online.\\n' => 'لا يوجد نموذج (موجود) مرتبط بـ: %s. لا يمكن للزائرين منح هذه الأنواع عبر الإنترنت.',
  '\\nEvery open donation type has a form.\\n' => 'يحتوي كل نوع من أنواع التبرعات المفتوحة على نموذج.',
  '\\nDefault currency:%s.\\n' => 'العملة الافتراضية: %s.',
  '\\niyzico is not set up for this currency (Donations › Payments › iyzico › currencies).\\n' => 'iyzico لم يتم إعداده لهذه العملة (التبرعات › الدفعات › iyzico › العملات).',
  '\\nBank accounts (transfer)\\n' => 'حسابات بنكية (تحويل)',
  '[[\'%dbank account is listed for bank transfer gifts.\', \'en\']]' . chr(0) . '[[\'%dbank accounts are listed for bank transfer gifts.\', \'en\']]' => 'حسابات %dالبنكية مدرجة لهدايا التحويل البنكي.' . chr(0) . 'الحساب البنكي %dمدرج لهدايا التحويل البنكي.' . chr(0) . 'حسابات %dالبنكية مدرجة لهدايا التحويل البنكي.' . chr(0) . 'حسابات %dالبنكية مدرجة لهدايا التحويل البنكي.' . chr(0) . 'حسابات %dالبنكية مدرجة لهدايا التحويل البنكي.' . chr(0) . 'حسابات %dالبنكية مدرجة لهدايا التحويل البنكي.',
  '\\nNo bank account is listed. They come from the theme (filter flxb_bank_accounts) and are used when recording bank transfer gifts.\\n' => 'لم يتم إدراج أي حساب مصرفي. وهي تأتي من السمة (عامل التصفية flxb_bank_accounts) ويتم استخدامها عند تسجيل هدايا التحويل البنكي.',
  '\\nReceipts and e-mails show "%s".\', \'en\']]' => 'تظهر الإيصالات ورسائل البريد الإلكتروني "%s".',
  '\\nNot set; receipts and e-mails use the site title "%s".\\n' => 'غير محدد؛ تستخدم الإيصالات ورسائل البريد الإلكتروني عنوان الموقع "%s".',
  '[[\'E-mail sending\\n' => 'إرسال البريد الإلكتروني',
  '\\nNot tested. Donor e-mails (recurring donation started, card declined) go out with wp_mail. The test sends one message to%s.\\n' => 'لم يتم اختباره. رسائل البريد الإلكتروني الخاصة بالمتبرع (بدأ التبرع المتكرر، تم رفض البطاقة) تخرج باستخدام wp_mail. يرسل الاختبار رسالة واحدة إلى%s.',
  '\\nSend test e-mail\\n' => 'إرسال بريد إلكتروني تجريبي',
  'Permalinks' => 'الروابط الدائمة',
  '\\nPlain permalinks are in use. Payment callbacks still work through ?rest_route=, but some hosts and security plugins block that; choose "Post name".\\n' => 'الروابط الدائمة العادية قيد الاستخدام. لا تزال عمليات رد الاتصال الخاصة بالدفع تعمل من خلال ?rest_route=، ولكن بعض المضيفين والمكونات الإضافية للأمان تحظر ذلك؛ اختر "اسم النشر".',
  '\\nPretty permalinks are on; REST callbacks use /wp-json/.\\n' => 'الروابط الدائمة الجميلة قيد التشغيل؛ تستخدم عمليات رد الاتصال REST /wp-json/.',
  '\\nThe site runs on HTTPS.\\n' => 'يعمل الموقع على HTTPS.',
  '\\nLocal test site without HTTPS. The live site must use HTTPS; payment providers refuse plain HTTP.\\n' => 'موقع اختبار محلي بدون HTTPS. يجب أن يستخدم الموقع المباشر HTTPS؛ يرفض موفرو الدفع استخدام HTTP العادي.',
  '\\nThe site address is not HTTPS. Card payments and payment callbacks need HTTPS (Settings › General, and an SSL certificate from the host).\\n' => 'عنوان الموقع ليس HTTPS. تحتاج عمليات الدفع بالبطاقة وعمليات رد الاتصال إلى HTTPS (الإعدادات › عام، وشهادة SSL من المضيف).',
  'General settings' => 'الإعدادات العامة',
  '\\nWordPress security keys (salts)\\n' => 'مفاتيح أمان ووردبريس (الأملاح)',
  '\\nMissing or weak in wp-config.php:%s. Saved iyzico cards are encrypted with these keys; set unique values once (https://api.wordpress.org/secret-key/1.1/salt/) and do not change them afterwards, or saved cards stop working.\\n' => 'مفقود أو ضعيف في wp-config.php: %s. يتم تشفير بطاقات iyzico المحفوظة بهذه المفاتيح؛ قم بتعيين قيم فريدة مرة واحدة (https://api.wordpress.org/secret-key/1.1/salt/) ولا تغيرها بعد ذلك، وإلا ستتوقف البطاقات المحفوظة عن العمل.',
  '\\nSet in wp-config.php. Saved iyzico cards are encrypted with them: do not change them, or saved cards stop working.\\n' => 'تم تعيينه في wp-config.php. يتم تشفير بطاقات iyzico المحفوظة بها: لا تقم بتغييرها، وإلا ستتوقف البطاقات المحفوظة عن العمل.',
  'Database tables' => 'جداول قاعدة البيانات',
  '\\nUp to date (%s).\\n' => 'محدث (%s).',
  '\\nTables are at version%1$s, expected%2$s. Deactivate and activate Flux Donate to update them.\\n' => 'الجداول موجودة في الإصدار%1$s، والمتوقع هو%2$s. قم بإلغاء تنشيط Flux Donate وتنشيطه لتحديثها.',
  '\\nNo iyzico keys to test.\\n' => 'لا توجد مفاتيح iyzico للاختبار.',
  '\\nsandbox\\n' => 'صندوق الحماية',
  '\\nConnected; iyzico accepted the keys (%s).\\n' => 'متصل; قبلت iyzico المفاتيح (%s).',
  '\\niyzico refused the keys (%1$s):%2$s. Check that the keys belong to this environment.\\n' => 'iyzico رفض المفاتيح (%1$s): %2$s. تأكد من أن المفاتيح تنتمي إلى هذه البيئة.',
  '\\nThis server could not reach its own wp-cron.php (%s). WP-Cron cannot start from visits; add a server cron job.\\n' => 'تعذر على هذا الخادم الوصول إلى ملف wp-cron.php الخاص به (%s). لا يمكن أن يبدأ WP-Cron من الزيارات؛ إضافة مهمة cron للخادم.',
  '\\nwp-cron.php answered; WP-Cron can start.\\n' => 'تم الرد على wp-cron.php؛ يمكن بدء تشغيل WP-Cron.',
  '\\nwp-cron.php answered with HTTP%d(blocked by the host or a security plugin?). Add a server cron job.\\n' => 'wp-cron.php تم الرد باستخدام HTTP%d(محظور بواسطة المضيف أو مكون إضافي للأمان؟). قم بإضافة مهمة cron للخادم.',
  '\\n[%s] Test e-mail from Flux Donate\\n' => '[%s] اختبار البريد الإلكتروني من Flux Donate',
  '\\nThis is a test from Donations › Settings › System check. If you can read it, donor e-mails can be sent.\\n' => 'هذا اختبار من التبرعات › الإعدادات › فحص النظام. إذا كنت تستطيع قراءتها، فيمكن إرسال رسائل البريد الإلكتروني للمانحين.',
  '\\nSent to%s. Check that it arrived (and not in spam).\\n' => 'تم الإرسال إلى%s. تأكد من وصولها (وليست في رسالة غير مرغوب فيها).',
  '\\nSending failed:%s. Set up SMTP (e.g. an SMTP plugin with your mail account).\\n' => 'فشل الإرسال: %s. قم بإعداد SMTP (على سبيل المثال، مكون إضافي لـ SMTP مع حساب البريد الخاص بك).',
  'unknown error' => 'خطأ غير معروف',
  '[[\'Donations on WooCommerce: donation types and sapling packages sold as hidden products, cart and checkout (iyzico, bank transfer with receipt upload), monthly donations, online and printed certificates, donors, campaigns and a donation dashboard. Includes Flux WooCommerce Bağış.\', \'en\']]' => 'التبرعات على WooCommerce: أنواع التبرعات وحزم الشتلات المباعة كمنتجات مخفية، وعربة التسوق والخروج (iyzico، التحويل البنكي مع تحميل الإيصال)، والتبرعات الشهرية، والشهادات عبر الإنترنت والمطبوعة، والمتبرعين، والحملات، ولوحة تحكم التبرع. يتضمن Flux WooCommerce Bağış.',
  '\\n%1$sdonation ·%2$sreceived%1$sdonations ·%2$sreceived\\n' . chr(0) . '\\n%1$sdonation ·%2$sreceived%1$sdonations ·%2$sreceived\\n' => ' تبرع%1$s· تم استلام %2$sتبرعات%1$s· تم استلام %2$s' . chr(0) . ' تبرع%1$s· تم استلام %2$sتبرعات%1$s· تم استلام %2$s' . chr(0) . ' تبرع%1$s· تم استلام %2$sتبرعات%1$s· تم استلام %2$s' . chr(0) . ' تبرع%1$s· تم استلام %2$sتبرعات%1$s· تم استلام %2$s' . chr(0) . ' تبرع%1$s· تم استلام %2$sتبرعات%1$s· تم استلام %2$s' . chr(0) . ' تبرع%1$s· تم استلام %2$sتبرعات%1$s· تم استلام %2$s',
  '\\n%1$spaid gift ·%2$s%1$spaid gifts ·%2$s\\n' . chr(0) . '\\n%1$spaid gift ·%2$s%1$spaid gifts ·%2$s\\n' => ' هدية مدفوعة%1$s· هدايا مدفوعة %2$s%1$s·%2$s' . chr(0) . ' هدية مدفوعة%1$s· هدايا مدفوعة %2$s%1$s·%2$s' . chr(0) . ' هدية مدفوعة%1$s· هدايا مدفوعة %2$s%1$s·%2$s' . chr(0) . ' هدية مدفوعة%1$s· هدايا مدفوعة %2$s%1$s·%2$s' . chr(0) . ' هدية مدفوعة%1$s· هدايا مدفوعة %2$s%1$s·%2$s' . chr(0) . ' هدية مدفوعة%1$s· هدايا مدفوعة %2$s%1$s·%2$s',
